"""Rebuild the research dossier from the evidence records shipped in the game."""
import json
from pathlib import Path

root = Path(__file__).resolve().parents[3]
text = (root / "native/godot/scripts/arsenal_diversity_data.gd").read_text(encoding="utf-8")

def constant(name):
    tail = text.split(f"const {name} := ", 1)[1]
    return json.JSONDecoder().raw_decode(tail)[0]

sources, profiles, roster = (constant(n) for n in ("SOURCES", "PROFILES", "ROSTER"))
names = dict(zip(profiles, ["ארה״ב", "סין", "האיחוד האירופי", "איראן", "רוסיה", "הודו", "יפן", "טורקיה", "ישראל", "בריטניה", "דרום קוריאה", "סעודיה", "ברזיל", "אינדונזיה", "אוקראינה", "צפון קוריאה", "מצרים", "אוסטרליה", "פקיסטן", "עיראק", "סוריה", "אפגניסטן", "ממשלת תימן", "החות׳ים", "אתיופיה", "ניגריה", "סודאן — SAF", "דרום סודאן"]))
roles = {"recoillessTeam": "צוות תותח ללא רתע", "wheeledHowitzer": "הוביצר מתנייע גלגלי", "shortRangeSAM": "הגנה אווירית קצרת טווח"}
domains = {"land": "קרקע ושריון", "air": "תעופה", "sea": "ים", "fires": "אש והגנה אווירית", "support": "תחזוקה והחלטת משחק", "limits": "גבולות הראיות"}
out = ["# DOMINION — הרחבת מגוון החימוש: מחקר לכל 28 הישויות", "", "תאריך מסמך: 12 באוקטובר 2026. חיתוך הראיות: 11 באוקטובר 2026.", "",
"המחקר מחבר בין סוג הנשק לתפקיד שהשחקן יכול להשתמש בו. נוספו שלושה תפקידים ו־20 בחירות מדינה–תפקיד, לצד תיק חימוש לכל 28 הישויות. לכל תיק שישה תחומים, מקורות ופריטים שלא הוענקו. זהו מחקר הרחבה של סגל המשחק, ולא סדר כוחות מלא או אימות של כל כלי שהיה בקוד קודם לכן.", "",
"## שיטת המחקר והבחנה בין מציאות למשחק", "",
"נבדקו דפי מפעילים, הודעות אספקה, דוחות או״ם, הערכות DIA, דוחות פיקוח וראיות מתועדות. עדיפות למקור ראשוני; באתיופיה ובפקיסטן אספקת SH-15 נשענת על דיווח Janes ומסומנת כך. הודעת יצרן מאשרת את טענת האספקה שלו, לא שיעור כשירות או הצלחה בקרב. SIPRI מתעד העברות ואינו מלאי כשיר בזמן אמת. הזמנה, אישור מכירה, ניסוי ותצוגה אינם נחשבים אוטומטית לשירות מבצעי.", "",
"הדוחות מ־2019/2021 על איראן וצפון קוריאה הם בסיס היסטורי. אין מהם אומדן לכשירות ב־2026. בסוריה, אפגניסטן, תימן וסודאן הופרדו רשימות עבר, ציוד שנתפס וכוחות בעלי שליטה שונה. סודאן ודרום סודאן הן שתי מדינות; RSF אינו דרום סודאן. ממשלת תימן והחות׳ים הם שני צדדי משחק בתוך מדינה אחת. EU הוא איגום משחקי של דוגמאות ממדינות חברות.", "",
"מחיר, נזק, טווח, מהירות, משך אימון ואוכלוסייה הם איזון משחקי. ייצור מייצג רכישה, הקצאת צוות ותחזוקה; הוא אינו טענה ליכולת ייצור מקומית. לא הוזנו כמויות מלאי משוערות. מסכי המשחק באנגלית, ולכן נוסח התיקים להלן תואם את התצוגה במשחק.", "",
"המחקר משלים את [מחקר הסגל הקודם](../FORCE-ROSTER-RESEARCH-2026-10-06.md), [מחקר הטילים והחימוש](../ARSENAL-RESEARCH-2026-10-06.md) ואת [מחקר הישויות האזוריות](../REGIONAL-ENTITIES-RESEARCH-2026-10-11.md). המקורות שם שייכים לשינויים ההם; רשימת Existing game roster במסך החדש היא לצורכי השוואה ואינה מאשרת אותם מחדש.", "",
"## מה השתנה בפועל", "",
"| תפקיד | החלטת משחק | גבול |", "|---|---|---|",
"| צוות תותח ללא רתע | תמיכה זולה מול רכב קל וביצורים, ללא מחקר טילים | טווח קצר, צוות חשוף, פחות כוח מול טנק מ־ATGM; בלי ירי אווירי |",
"| הוביצר גלגלי | תנועה מהירה מול תותח נגרר; אותה מערכת הפגזה ותצפית | מיגון קל, יקר מנגרר; אין תוספת טווח מציאותי בקילומטרים למפה |",
"| הגנה אווירית קצרת טווח | ליווי קרקעי זול יותר מ־SAM ארוך טווח מול מטוסים וכטב״מים | בלי ירי קרקע, בלי הפגזה ובלי יירוט אירועי טילים אסטרטגיים |", "",
"כל התפקידים מחוברים לייצור, למחקר הנדרש, לבחירת AI היריב, למודלי תלת־ממד ולשמירות הקיימות. ההגנה הקצרה מייצגת תפקיד משותף למערכות שונות; אין טענה שלכולן אותו חיישן, טיל או ביצועים. לצוות ללא רתע בחירת התחמושת מופשטת; אין מנגנון ייעודי לעשן או תאורה.", "",
"גישה במשחק: Defence → Arsenal. בחירת מדינה ואחד מששת התחומים. מקורות נפתחים רק בלחיצה. למדינה שלך, כשיש מתקן מתאים, יש מעבר לרשימת הייצור שלו. לחיצה על נשק אינה קונה יחידה ולא עוקפת מחקר.", "",
"## 20 בחירות הייצור החדשות", "", "| מדינה | סוג | דגם | מעמד ראיות | מקור |", "|---|---|---|---|---|"]
for role, countries in roster.items():
    for country, (model, source, status) in countries.items():
        title, url = sources[source]
        out.append(f"| {names[country]} | {roles[role]} | {model} | {status} | [{title}]({url}) |")
out += ["", "## התיקים לכל מדינה", ""]
for i, (country, profile) in enumerate(profiles.items(), 1):
    out += [f"### {i}. {names[country]} — `{country}`", ""]
    for key, heading in domains.items():
        out += [f"**{heading}:** {profile[key]}", ""]
    additions = [model for entries in roster.values() for c, (model, _, _) in entries.items() if c == country]
    out += ["**נוסף לייצור:** " + ("; ".join(additions) if additions else "לא הוענק דגם חדש ללא ראיות מספיקות; התיק והסגל הקיים זמינים במשחק."), "", "**מעקב / לא הוענק במחקר זה:**", ""]
    out += ["- " + item for item in profile["watch"]]
    out += ["", "**מקורות התיק:** " + "; ".join(f"[{sources[s][0]}]({sources[s][1]})" for s in profile["sources"]), ""]
out += ["## אימות והיקף מסירה", "", "בדיקות ההרחבה: 293 הצלחות, אפס כישלונות; בדיקות הסגל המורחב: 674 הצלחות, אפס כישלונות. נבדקו כל המדינות וששת התחומים, שיוך למפעיל, מחקר, תור ייצור, ירי ופגיעה, מגבלות מטרות, ראייה ו־JSON save/restore. בדיקות גרפיות, רגרסיה ויצוא מפורטים ב־HANDOFF.md לאחר השלמתם.", "", "הרחבה זו משנה את המשחק הפעיל ב־native/godot. גרסת הדפדפן הישנה אינה מקבלת כאן מסך או יחידות מקבילות. מסירה לקלוד נעשית בקובץ התיאום המשותף; הודעת מסירה אינה אישור שקרא או פרסם.", ""]
(root / "native/ARSENAL-DIVERSITY-RESEARCH-2026-10-12.md").write_text("\n".join(out).replace("](../", "]("), encoding="utf-8")
print(f"Wrote 28 dossiers, {sum(map(len, roster.values()))} operator choices, {len(sources)} source records")
